const updateSessionFromActivitySignal = `-- name: UpdateSessionFromActivitySignal :execrows
UPDATE sessions SET
    activity_state = ?1,
    activity_last_at = ?2,
    first_signal_at = ?3,
    agent_session_id = ?4,
    agent_session_id_launch_id = ?5,
    latest_user_prompt = ?6,
    latest_user_prompt_at = ?7,
    latest_assistant_update = ?8,
    native_transcript_path = ?9,
    updated_at = ?10
WHERE sessions.id = ?11
  AND sessions.is_terminated = 0
  AND sessions.harness = ?12
  AND sessions.session_mode = ?13
  AND (
      (
          ?13 <> 'chat'
          AND sessions.runtime_launch_id = ?14
      )
      OR
      (
          ?13 = 'chat'
          AND sessions.controller_generation = ?15
      )
  )
  AND NOT EXISTS (
      SELECT 1
      FROM agent_switches AS active_switch
      WHERE active_switch.session_id = sessions.id
        AND active_switch.from_harness = sessions.harness
        AND active_switch.state IN (
            'stopping_source', 'source_stopped', 'starting_target'
        )
  )
`

type UpdateSessionFromActivitySignalParams struct {
	ActivityState                domain.ActivityState
	ActivityLastAt               time.Time
	FirstSignalAt                sql.NullTime
	AgentSessionID               string
	AgentSessionIDLaunchID       string
	LatestUserPrompt             string
	LatestUserPromptAt           sql.NullTime
	LatestAssistantUpdate        string
	NativeTranscriptPath         string
	UpdatedAt                    time.Time
	ID                           domain.SessionID
	ExpectedHarness              domain.AgentHarness
	ExpectedSessionMode          domain.SessionMode
	ExpectedRuntimeLaunchID      string
	ExpectedControllerGeneration string
}

// Lifecycle reads the session before reducing a hook. Fence the resulting
// narrow write against a concurrent ownership transfer, and reject every
// callback while the still-projected owner is the source being torn down.
// Target hooks remain allowed after atomic activation moves both the session
// owner/generation and switch state out of these source-side phases.
func (q *Queries) UpdateSessionFromActivitySignal(ctx context.Context, arg UpdateSessionFromActivitySignalParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateSessionFromActivitySignal,
		arg.ActivityState,
		arg.ActivityLastAt,
		arg.FirstSignalAt,
		arg.AgentSessionID,
		arg.AgentSessionIDLaunchID,
		arg.LatestUserPrompt,
		arg.LatestUserPromptAt,
		arg.LatestAssistantUpdate,
		arg.NativeTranscriptPath,
		arg.UpdatedAt,
		arg.ID,
		arg.ExpectedHarness,
		arg.ExpectedSessionMode,
		arg.ExpectedRuntimeLaunchID,
		arg.ExpectedControllerGeneration,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
